import{c as t,Q as e,j as s,m as i}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"HTML 作為主要輸出格式（HTML-First Strategy）","description":"","frontmatter":{},"headers":[],"relativePath":"research/best-practices/31-html-output-strategy.md","filePath":"research/best-practices/31-html-output-strategy.md","lastUpdated":1779800848000}'),n={name:"research/best-practices/31-html-output-strategy.md"};function r(o,a,l,p,d,c){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="html-作為主要輸出格式-html-first-strategy" tabindex="-1">HTML 作為主要輸出格式（HTML-First Strategy） <a class="header-anchor" href="#html-作為主要輸出格式-html-first-strategy" aria-label="Permalink to &quot;HTML 作為主要輸出格式（HTML-First Strategy）&quot;">​</a></h1><blockquote><p>來源：<a href="https://claude.com/blog/using-claude-code-the-unreasonable-effectiveness-of-html" target="_blank" rel="noreferrer">Using Claude Code: The unreasonable effectiveness of HTML</a><br> 作者：Thariq Shihipar（Anthropic）<br> 整理日期：2026-06-05<br> 原文日期：2026-05-20</p></blockquote><hr><h2 id="核心主張" tabindex="-1">核心主張 <a class="header-anchor" href="#核心主張" aria-label="Permalink to &quot;核心主張&quot;">​</a></h2><p>HTML 優於 Markdown 的原因：資訊密度、視覺清晰度、可分享性、互動能力、資料導入效率。Thariq 已幾乎完全放棄 Markdown，轉向「HTML maximalist」工作流。</p><hr><h2 id="為何-html-優於-markdown" tabindex="-1">為何 HTML 優於 Markdown <a class="header-anchor" href="#為何-html-優於-markdown" aria-label="Permalink to &quot;為何 HTML 優於 Markdown&quot;">​</a></h2><table tabindex="0"><thead><tr><th>面向</th><th>Markdown 限制</th><th>HTML 優勢</th></tr></thead><tbody><tr><td>資訊密度</td><td>平面文字 + 有限表格</td><td>表格、SVG、CSS、可摺疊區塊、空間布局</td></tr><tr><td>視覺清晰度</td><td>超過 100 行難以閱讀</td><td>Tabs、分層、響應式設計</td></tr><tr><td>分享</td><td>需要附件</td><td>單一 URL，同事真的會看</td></tr><tr><td>互動</td><td>靜態</td><td>Slider、旋鈕、自訂編輯器，可匯出回 prompt</td></tr><tr><td>資料導入</td><td>N/A</td><td>File system、MCP（Slack/Linear）、瀏覽器、git history</td></tr></tbody></table><hr><h2 id="五大使用場景與-prompt-範例" tabindex="-1">五大使用場景與 Prompt 範例 <a class="header-anchor" href="#五大使用場景與-prompt-範例" aria-label="Permalink to &quot;五大使用場景與 Prompt 範例&quot;">​</a></h2><h3 id="_1-規格與探索-specs-exploration" tabindex="-1">1. 規格與探索（Specs &amp; Exploration） <a class="header-anchor" href="#_1-規格與探索-specs-exploration" aria-label="Permalink to &quot;1. 規格與探索（Specs &amp; Exploration）&quot;">​</a></h3><p>視覺化多個解法，讓選擇更容易：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generate 6 distinctly different approaches to [problem]...</span></span>
<span class="line"><span>lay them out as a single HTML file in a grid</span></span></code></pre></div><h3 id="_2-code-review" tabindex="-1">2. Code Review <a class="header-anchor" href="#_2-code-review" aria-label="Permalink to &quot;2. Code Review&quot;">​</a></h3><p>直觀理解 PR 變更：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Create an HTML artifact reviewing this PR... focus on streaming/backpressure logic.</span></span>
<span class="line"><span>Render actual diff with inline margin annotations</span></span></code></pre></div><h3 id="_3-設計與原型" tabindex="-1">3. 設計與原型 <a class="header-anchor" href="#_3-設計與原型" aria-label="Permalink to &quot;3. 設計與原型&quot;">​</a></h3><p>測試 animation 並互動調參：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Create a HTML file with several sliders controlling animation parameters...</span></span>
<span class="line"><span>try different options on this animation, give me a copy button</span></span></code></pre></div><h3 id="_4-報告與研究" tabindex="-1">4. 報告與研究 <a class="header-anchor" href="#_4-報告與研究" aria-label="Permalink to &quot;4. 報告與研究&quot;">​</a></h3><p>資料視覺化合成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Produce a single HTML explainer page: diagram of token-bucket flow,</span></span>
<span class="line"><span>key code snippets annotated, key numbers</span></span></code></pre></div><h3 id="_5-客製編輯器" tabindex="-1">5. 客製編輯器 <a class="header-anchor" href="#_5-客製編輯器" aria-label="Permalink to &quot;5. 客製編輯器&quot;">​</a></h3><p>打造任務專屬介面：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Make draggable cards across Now/Next/Later/Cut columns...</span></span>
<span class="line"><span>Add a copy as Markdown button</span></span></code></pre></div><hr><h2 id="快速開始" tabindex="-1">快速開始 <a class="header-anchor" href="#快速開始" aria-label="Permalink to &quot;快速開始&quot;">​</a></h2><p>不需要預設模板，直接 prompt：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt; make an HTML file</span></span>
<span class="line"><span>&gt; create an HTML artifact showing [your content]</span></span></code></pre></div><p><strong>避免的常見錯誤：</strong></p><ul><li>過度設計（不需要預設模板）</li><li>過早把 pattern 變成 Skill（先有機地實驗）</li><li>擔心 token 用量（1M context window 讓這不再是問題）</li></ul><hr><h2 id="實作建議" tabindex="-1">實作建議 <a class="header-anchor" href="#實作建議" aria-label="Permalink to &quot;實作建議&quot;">​</a></h2><ul><li>HTML 作為<strong>持久參考工件</strong>：可跨 session 再次載入做為 context</li><li>互動 HTML 允許用戶調整設計並將修改後的參數匯回 prompt</li><li>優先用 HTML 做 code review 的 artifact，比文字摘要更清晰</li><li>增加使用者持續參與 AI 生成工作的可能性（而非被動消費輸出）</li></ul><hr><h2 id="關鍵洞察" tabindex="-1">關鍵洞察 <a class="header-anchor" href="#關鍵洞察" aria-label="Permalink to &quot;關鍵洞察&quot;">​</a></h2><blockquote><p>&quot;HTML outperforms Markdown as an output format because it enables richer information density, improved visual clarity, easier sharing, interactive capabilities, and better context ingestion.&quot;</p></blockquote><p>這是 Claude Code 特有優勢：可讀取 file system、MCP connector、web browser、git history，是在 claude.ai 或 Claude Design 介面操作所沒有的能力。</p>`,38)])])}const b=t(n,[["render",r]]);export{u as __pageData,b as default};
